"""Reproducible Spanish→English placement course. Author review remains pending."""
from pathlib import Path
import json,re
R=Path(__file__).resolve().parent.parent
rows=json.loads((R/'content/place-directions/scenarios.json').read_text())
# Glosses describe the form actually encountered, including command forms.
gloss='''martillo=hammer;mesa=table;llave=wrench / key (context);caja=box;destornillador=screwdriver;mochila=backpack;casco=helmet;puerta=door;libro=book;silla=chair;suelo=floor;taller=workshop;cinta=tape;oficina=office;pasillo=hallway;habitación=room;tienda=store;esquina=corner;calle=street;herramientas=tools;camioneta=pickup truck;nota=note;visita=visitor;tarea=task;objetos=objects;lugares=places;instrucción=instruction;referencia=reference point;posición=position;destino=destination;secuencia=sequence;pareja=partner;paso=way / step;primero=first;después=after / afterwards;antes=before;ahora=now;encima=on top;debajo=under;dentro=inside;fuera=outside;lado=side;delante=in front;detrás=behind;entre=between;cerca=near;lejos=far;aquí=here;ahí=there;allí=over there;izquierda=left;derecha=right;recto=straight ahead;fondo=far end;frente=front;arriba=up / above;abajo=down / below;junto=beside (with a);correcta=correct (feminine);equivocada=wrong (feminine);abierta=open (feminine);cerrada=closed (feminine);azul=blue;roja=red (feminine);verde=green;principal=main;distintos=different (masculine plural);nueva=new (feminine);dos=two;otra=another (feminine);ambos=both;mi=my;tu=your (informal);ti=you (after preposition);está=is (location / state);están=are (location / state);estaba=was (location / state);hay=there is / there are;había=there was / there were;pon=put (tú command);ponlo=put it (masculine);ponla=put it (feminine);pongan=put (ustedes command);levanta=pick up (tú command);lleva=take (tú command);trae=bring (tú command);tráelo=bring it (masculine);saca=take out (tú command);mételo=put it inside (masculine);abre=open (tú command);cierra=close (tú command);deja=leave (tú command);déjalo=leave it (masculine);déjala=leave it (feminine);espera=wait (tú command);para=stop (command) / for;sube=go up / bring up (command);baja=go down / bring down (command);sigue=continue (tú command);siga=continue (usted command);gira=turn (tú command);gire=turn (usted command);pasa=pass / go through (command);camina=walk (command);regresa=return (command);recoge=collect / pick up (command);dónde=where (question);cuál=which (question);puedes=you can (tú);debe=must / should;cabe=fits;queda=is situated / remains;bloquea=blocks;necesito=I need;veo=I see;busca=look for (command);muevas=move (tú subjunctive);muévela=move it (feminine command);indica=indicate (command) / indicates;describe=describe (command);confirma=confirm (command);rodea=go around (command);llevé=I took;levanté=I picked up;dejé=I left;digo=I say;refiero=I refer;elige=choose (command);léela=read it (feminine command);propón=suggest (command);explica=explain (command);sirve=works / is useful;dime=tell me;vea=see (usted subjunctive);saques=take out (tú subjunctive);necesitamos=we need;cambié=I changed;termina=ends;empieza=starts;organiza=arrange (command);ruta=route;confirmación=confirmation'''
D=dict(x.split('=',1) for x in gloss.split(';'))
base=[('Ana prepara una tarea con su pareja.','Ana prepares a task with her partner.'),('La pareja escucha la instrucción antes de mover los objetos.','The partner listens to the instruction before moving the objects.')]
extra=[('La referencia indica el lugar desde el que se describe la posición.','The reference point indicates the place from which the position is described.'),('El destino no cambia hasta que la pareja confirme la instrucción.','The destination does not change until the partner confirms the instruction.'),('Si la secuencia no está clara, la pareja pide una confirmación.','If the sequence is unclear, the partner asks for confirmation.'),('Ambos comparan el resultado con la posición que se había indicado.','Both compare the result with the position that had been indicated.')]
verbs=[dict(infinitive='poner',native='to put / place',forms=dict(zip(['yo','tú','él_ella_usted','nosotros','ellos_ustedes'],['pongo','pones','pone','ponemos','ponen'])),example={'target':'Pongo la llave dentro de la caja.','native':'I put the wrench inside the box.'},note='Present: pong-o; tú command: pon. With a masculine object: ponlo.'),dict(infinitive='estar',native='to be (location / state)',forms=dict(zip(['yo','tú','él_ella_usted','nosotros','ellos_ustedes'],['estoy','estás','está','estamos','están'])),example={'target':'La caja está debajo de la mesa.','native':'The box is under the table.'},note='Use estar for an object’s location: está; plural objects: están.'),dict(infinitive='llevar',native='to take / carry',forms=dict(zip(['yo','tú','él_ella_usted','nosotros','ellos_ustedes'],['llevo','llevas','lleva','llevamos','llevan'])),example={'target':'Llevo la mochila a la oficina.','native':'I take the backpack to the office.'},note='Regular -ar present: llev-o, llev-as. Tú command: lleva.'),dict(infinitive='seguir',native='to follow / continue',forms=dict(zip(['yo','tú','él_ella_usted','nosotros','ellos_ustedes'],['sigo','sigues','sigue','seguimos','siguen'])),example={'target':'Sigo recto hasta la puerta.','native':'I go straight ahead to the door.'},note='Present e→i except nosotros; yo sigo. Tú command: sigue; usted: siga.'),dict(infinitive='mover',native='to move',forms=dict(zip(['yo','tú','él_ella_usted','nosotros','ellos_ustedes'],['muevo','mueves','mueve','movemos','mueven'])),example={'target':'Muevo la silla al lado de la mesa.','native':'I move the chair next to the table.'},note='Present o→ue except nosotros. Tú: mueve; negative tú: no muevas.')]
practice={};built=[]
for row in rows:
 stage,n=row['stage'],row['n'];module='place-directions' if stage=='core' else stage+'-place-directions'
 es,en=row['scene'];cmd,eng=row['command']
 # Scenario-specific opening followed by an explicit instruction exchange, not a glossary passage.
 pairs=[(es,en),tuple(row['context']),('Ana lee la instrucción: '+cmd,'Ana reads the instruction: '+eng),base[1],('Su pareja pregunta: ¿Dónde debe quedar al terminar?','Her partner asks: Where should it end up when finished?'),tuple(row['resolution']),('La pareja realiza la tarea y comprueba el resultado.','The partner performs the task and checks the result.')]
 phrases=[(cmd,eng),(es,en),('¿Puedes repetir la instrucción?','Can you repeat the instruction?'),('Confirma el destino antes de moverlo.','Confirm the destination before moving it.')]
 if stage=='master':
  pairs[4:4]=extra
  pairs.append(('Al final, ambos explican qué cambió y por qué eligieron ese lugar.','At the end, both explain what changed and why they chose that place.'))
  phrases += [('¿Desde dónde describes la posición?','From where are you describing the position?'),('Si cambia el destino, confirma la nueva secuencia.','If the destination changes, confirm the new sequence.')]
 # Exact headword/form glosses drawn from the actual passage; specialist compounds retained below.
 tokens=list(dict.fromkeys(re.findall(r'[\wáéíóúñü]+',(' '.join(x[0] for x in pairs)).lower())))
 scene_tokens=re.findall(r'[\wáéíóúñü]+',(es+' '+cmd).lower())
 priority=list(dict.fromkeys(scene_tokens+tokens))
 terms=[{'es':t,'en':D[t],'kind':'term'} for t in priority if t in D][:12 if stage=='master' else 8]
 assert len(terms)==(12 if stage=='master' else 8),(row['title'],terms)
 words=terms+[{'es':a,'en':b,'kind':'phrase'} for a,b in phrases]
 objective=f"{row['title']}: understand and carry out the instruction, identify the reference point, then describe or confirm the destination."
 speaking=f"Role-play {row['title'].lower()}. Start with: {cmd} Ask your partner to clarify one reference point, complete the task in words, and confirm the final position."
 lesson=dict(n=n,title=row['title'],objective=objective,focus=row['focus'],words=words,speaking=speaking,partnerRole='Spanish-speaking partner giving placement and route instructions',openingLine=cmd,readingTemplate=f'seed-es-{module}-lesson-{n}')
 if stage=='master':lesson.update(grammar={'focus':row['focus'],'examples':[{'es':a,'en':b} for a,b in phrases[:2]]},lessonType=['Teach-back','Case','People','Document','Capstone'][(n-1)%5],block='ABCDE'[(n-1)//4])
 content=dict(passage=dict(title=row['title'],target=[a for a,b in pairs],native=[b for a,b in pairs]),words=words,verbs=verbs[:5 if stage=='master' else 3])
 built.append(dict(stage=stage,lesson=lesson,content=content))
 practice.setdefault(module,{})[str(n)]=dict(stage=stage,reading=content['passage'],speaking=speaking,openingLine=cmd,partnerRole=lesson['partnerRole'])
for stage in ['foundation','core','master']:
 selected=[r for r in built if r['stage']==stage];module='place-directions' if stage=='core' else stage+'-place-directions'
 c=dict(version=1,module=module,language='Spanish',nativeLanguage='English',headline=f'Place & Directions · {stage.title()}',threshold='Understand, give, clarify, and carry out practical placement and route instructions.',reviewed=False,lessons=[r['lesson'] for r in selected])
 if stage!='core':c.update(baseModule='place-directions',stage=stage)
 dest=R/('src/data/place-directions-core.json' if stage=='core' else f'src/data/core60/es/{module}.json');dest.write_text(json.dumps(c,ensure_ascii=False,indent=2)+'\n')
 (R/f'public/lesson-content/es/{module}.json').write_text(json.dumps(dict(version=1,module=module,language='Spanish',nativeLanguage='English',reviewed=False,lessons={str(r['lesson']['n']):r['content'] for r in selected}),ensure_ascii=False,indent=2)+'\n')
(R/'src/data/place-directions-practice.json').write_text(json.dumps(practice,ensure_ascii=False,indent=2)+'\n')
(R/'content/place-directions/lessons.json').write_text(json.dumps(built,ensure_ascii=False,indent=2)+'\n')
p=R/'public/lesson-content/index.json';idx=json.loads(p.read_text());idx['files']=[x for x in idx['files'] if x['module'] not in practice]
for module,ls in practice.items():idx['files'].append(dict(language='es',module=module,lessons=len(ls),bytes=(R/f'public/lesson-content/es/{module}.json').stat().st_size,reviewed=False))
idx['files'].sort(key=lambda x:(x['language'],x['module']));p.write_text(json.dumps(idx,ensure_ascii=False)+'\n')
print('Built 10 Foundation + 30 Core + 20 Master, Spanish / English, author review pending.')
